"""In-memory ``messageId`` cache, in-flight registry, and cached-task replay."""

from __future__ import annotations

import asyncio
import time
from collections.abc import AsyncGenerator
from datetime import datetime, timezone
from typing import TYPE_CHECKING, Optional

from a2a.server.events import EventQueue
from a2a.types import (
    Message,
    MessageSendParams,
    Task,
    TaskArtifactUpdateEvent,
    TaskState,
    TaskStatus,
    TaskStatusUpdateEvent,
)
from pydantic import BaseModel, ConfigDict, Field

if TYPE_CHECKING:
    from a2a.server.events import Event

from rasa.core.a2a_server.config import DEFAULT_A2A_TASK_TIMEOUT_SECONDS

# Terminal / interactive-terminal states safe to replay for duplicate ``messageId``.
CACHEABLE_TASK_STATES = frozenset(
    {
        TaskState.completed,
        TaskState.input_required,
        TaskState.rejected,
        TaskState.failed,
        TaskState.canceled,
        TaskState.auth_required,
    }
)

DEFAULT_A2A_MESSAGE_CACHE_TTL_SECONDS = DEFAULT_A2A_TASK_TIMEOUT_SECONDS

CacheKey = tuple[str, str]
"""Idempotency key for one A2A ``message/send`` (or stream) request.

A 2-tuple ``(context_id, message_id)``:

- ``context_id``: A2A conversation / session id (scopes dedup to one dialog).
- ``message_id``: client ``Message.messageId``; retries with the same pair are
  treated as the same logical send.

Used as the dict/set key for terminal-task replay and the in-flight registry
(duplicate while still processing → HTTP 409).
"""


class A2AMessageCacheEntry(BaseModel):
    """One cached terminal outcome for a ``(context_id, message_id)`` pair."""

    model_config = ConfigDict(frozen=True)

    recorded_at: float = Field(description="``time.time()`` when the entry was stored")
    task: Task = Field(description="Deep copy of the final Task returned to the client")


class A2AMessageCache:
    """TTL cache of terminal tasks plus an in-flight registry per ``messageId``."""

    def __init__(
        self, *, ttl_seconds: int = DEFAULT_A2A_MESSAGE_CACHE_TTL_SECONDS
    ) -> None:
        self._ttl_seconds = ttl_seconds
        self._entries: dict[CacheKey, A2AMessageCacheEntry] = {}
        self._in_flight: set[CacheKey] = set()
        self._lock = asyncio.Lock()

    @property
    def ttl_seconds(self) -> int:
        return self._ttl_seconds

    async def get(self, context_id: str, message_id: str) -> Task | None:
        """Return a cached terminal ``Task`` copy, or ``None`` if missing or expired."""
        key = (context_id, message_id)
        async with self._lock:
            entry = self._entries.get(key)
            if entry is None:
                return None
            if self._is_expired(entry.recorded_at):
                del self._entries[key]
                return None
            return entry.task.model_copy(deep=True)

    async def try_begin_in_flight(self, context_id: str, message_id: str) -> bool:
        """Register in-flight processing. Returns ``False`` if already in flight."""
        key = (context_id, message_id)
        async with self._lock:
            if key in self._in_flight:
                return False
            self._in_flight.add(key)
            return True

    async def end_in_flight(self, context_id: str, message_id: str) -> None:
        """Clear in-flight registration (no-op when not registered)."""
        key = (context_id, message_id)
        async with self._lock:
            self._in_flight.discard(key)

    async def record(self, context_id: str, message_id: str, task: Task) -> None:
        """Store a deep copy of ``task`` and evict expired entries."""
        key = (context_id, message_id)
        async with self._lock:
            self._purge_expired_locked()
            self._entries[key] = A2AMessageCacheEntry(
                recorded_at=time.time(),
                task=task.model_copy(deep=True),
            )

    async def close(self) -> None:
        """Clear all cached and in-flight state (server shutdown)."""
        async with self._lock:
            self._entries.clear()
            self._in_flight.clear()

    def _is_expired(self, recorded_at: float) -> bool:
        return (time.time() - recorded_at) > self._ttl_seconds

    def _purge_expired_locked(self) -> None:
        expired = [
            key
            for key, entry in self._entries.items()
            if self._is_expired(entry.recorded_at)
        ]
        for key in expired:
            del self._entries[key]


def cache_key_from_message(
    *, context_id: str | None, message_id: str | None
) -> Optional[CacheKey]:
    """Build a ``CacheKey`` when both A2A identifiers are non-empty."""
    if context_id and message_id:
        return context_id, message_id
    return None


def cache_key_from_dispatch(
    message: Message,
    *,
    context_id_fallback: str | None = None,
) -> Optional[CacheKey]:
    """Build a dedup key from ``message`` ids with optional context fallback."""
    context_id = message.context_id or context_id_fallback
    return cache_key_from_message(
        context_id=context_id,
        message_id=message.message_id,
    )


def should_cache_task(task: Task) -> bool:
    """Whether ``task`` is a terminal outcome worth caching for idempotent replay."""
    state = task.status.state
    if state not in CACHEABLE_TASK_STATES:
        return False
    if state != TaskState.failed:
        return True
    return _failed_task_is_structured_pattern_outcome(task)


def _failed_task_is_structured_pattern_outcome(task: Task) -> bool:
    """Distinguish pattern ``failed`` (cacheable) from executor fast-fail paths."""
    message = task.status.message
    if message is None:
        return False
    for part in message.parts:
        root = part.root
        if getattr(root, "kind", None) == "data":
            return True
    return False


async def replay_cached_task_to_queue(
    cached_task: Task,
    event_queue: EventQueue,
    *,
    task_id: str,
    context_id: str,
) -> None:
    """Publish terminal status and artifacts from ``cached_task`` to ``event_queue``."""
    timestamp = datetime.now(timezone.utc).isoformat()

    for artifact in cached_task.artifacts or []:
        await event_queue.enqueue_event(
            TaskArtifactUpdateEvent(
                task_id=task_id,
                context_id=context_id,
                artifact=artifact.model_copy(deep=True),
                append=False,
                last_chunk=True,
            )
        )

    status_message = (
        cached_task.status.message.model_copy(deep=True)
        if cached_task.status.message is not None
        else None
    )
    await event_queue.enqueue_event(
        TaskStatusUpdateEvent(
            task_id=task_id,
            context_id=context_id,
            final=True,
            status=TaskStatus(
                state=cached_task.status.state,
                message=status_message,
                timestamp=timestamp,
            ),
        )
    )
    await event_queue.close()


def task_for_replay(
    cached_task: Task,
    *,
    task_id: str,
    context_id: str,
) -> Task:
    """Build a ``Task`` snapshot for the current request ids from a cache entry."""
    return Task(
        id=task_id,
        context_id=context_id,
        status=cached_task.status.model_copy(deep=True),
        artifacts=[a.model_copy(deep=True) for a in cached_task.artifacts or []],
        history=[m.model_copy(deep=True) for m in cached_task.history or []],
        metadata=cached_task.metadata,
    )


def replay_ids_for_message(
    cached_task: Task, params: MessageSendParams
) -> tuple[str, str]:
    """Resolve ``task_id`` and ``context_id`` for replay from the inbound message."""
    message = params.message
    task_id = message.task_id or cached_task.id
    context_id = message.context_id or cached_task.context_id
    return task_id, context_id


def task_for_replay_from_params(cached_task: Task, params: MessageSendParams) -> Task:
    """Return a cache replay ``Task`` with ids taken from ``params.message``."""
    task_id, context_id = replay_ids_for_message(cached_task, params)
    return task_for_replay(cached_task, task_id=task_id, context_id=context_id)


def capture_stream_final_task(current: Task | None, event: object) -> Task | None:
    """Update the task snapshot used for stream cache recording.

    Prefer a full ``Task`` event. A final ``TaskStatusUpdateEvent`` is used only
    when no ``Task`` has been seen yet (SDK may emit status-only terminals).
    """
    if isinstance(event, Task):
        return event
    if current is not None:
        return current
    if isinstance(event, TaskStatusUpdateEvent) and event.final:
        return Task(
            id=event.task_id,
            context_id=event.context_id,
            status=event.status,
        )
    return current


async def replay_cached_stream(
    cached_task: Task,
    params: MessageSendParams,
) -> AsyncGenerator[Event, None]:
    """Yield stream events that reproduce a cached terminal outcome."""
    task_id, context_id = replay_ids_for_message(cached_task, params)
    timestamp = datetime.now(timezone.utc).isoformat()

    for artifact in cached_task.artifacts or []:
        yield TaskArtifactUpdateEvent(
            task_id=task_id,
            context_id=context_id,
            artifact=artifact.model_copy(deep=True),
            append=False,
            last_chunk=True,
        )

    status_message = (
        cached_task.status.message.model_copy(deep=True)
        if cached_task.status.message is not None
        else None
    )
    yield TaskStatusUpdateEvent(
        task_id=task_id,
        context_id=context_id,
        final=True,
        status=TaskStatus(
            state=cached_task.status.state,
            message=status_message,
            timestamp=timestamp,
        ),
    )

    yield task_for_replay(cached_task, task_id=task_id, context_id=context_id)
